insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,9,'Why can Masterful Notes make delivery easier?',true,'[{"key":"A","text":"They are easier to see"},{"key":"B","text":"They are easier to follow"},{"key":"C","text":"They are easier to speak from naturally"},{"key":"D","text":"They help make the message feel cleaner and more manageable"}]'::jsonb,ARRAY['A','B','C','D']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-designed';
