insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,0,'What do Masterful Notes enable in addition to helping you stay on message?',false,'[{"key":"A","text":"Longer presentations"},{"key":"B","text":"The Pause Delivery technique"},{"key":"C","text":"More detailed slides"},{"key":"D","text":"Faster memorization"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-delivered';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,1,'What are the three elements of the Pause Delivery technique?',true,'[{"key":"A","text":"Brisk Rate of Words"},{"key":"B","text":"Clear bursts of ideas separated by silent pauses"},{"key":"C","text":"Purposeful eye contact with the audience"},{"key":"D","text":"Complete memorization of every sentence"}]'::jsonb,ARRAY['A','B','C']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-delivered';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,2,'When beginning the Masterful Notes process, what should you take in from your notes?',false,'[{"key":"A","text":"One paragraph"},{"key":"B","text":"One idea or line of information"},{"key":"C","text":"The entire presentation"},{"key":"D","text":"Only the opening headline"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-delivered';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,3,'What should you do after looking up at your audience and before delivering an idea?',false,'[{"key":"A","text":"Read the next line"},{"key":"B","text":"Pause for a second or two"},{"key":"C","text":"Look back down at your notes"},{"key":"D","text":"Speed up your Rate of Words"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-delivered';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,4,'What is the purpose of the first pause?',false,'[{"key":"A","text":"To create anticipation and focus the audience"},{"key":"B","text":"To signal that the presentation is ending"},{"key":"C","text":"To allow the speaker to change slides"},{"key":"D","text":"To memorize the next paragraph"}]'::jsonb,ARRAY['A']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-delivered';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,5,'After delivering an idea, what should you do?',false,'[{"key":"A","text":"Immediately look down at your notes"},{"key":"B","text":"Move to the next sentence without stopping"},{"key":"C","text":"Pause again while maintaining eye contact"},{"key":"D","text":"Repeat the idea more loudly"}]'::jsonb,ARRAY['C']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-delivered';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,6,'What happens when you use Masterful Notes and the Pause Delivery technique well?',true,'[{"key":"A","text":"You provide the audience with substantial eye contact"},{"key":"B","text":"You give eye contact at meaningful moments before and after ideas"},{"key":"C","text":"You sound as though you are thinking clearly in real time"},{"key":"D","text":"You appear as though you are reading a script"}]'::jsonb,ARRAY['A','B','C']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-delivered';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,7,'As speakers become more experienced, what may they be able to do?',false,'[{"key":"A","text":"Deliver without pausing"},{"key":"B","text":"Pick up two or three lines at a time"},{"key":"C","text":"Stop using eye contact"},{"key":"D","text":"Return to reading full sentences"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-delivered';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,8,'Why might a speaker vary the length of the first and second pauses?',false,'[{"key":"A","text":"To emphasize different ideas"},{"key":"B","text":"To create the right rhythm"},{"key":"C","text":"To make the technique their own"},{"key":"D","text":"All of the above"}]'::jsonb,ARRAY['D']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-delivered';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,9,'What is the ultimate goal of the Pause Delivery technique?',false,'[{"key":"A","text":"To imitate a famous speaker exactly"},{"key":"B","text":"To sound mechanical and rehearsed"},{"key":"C","text":"To make the technique authentic to your own style"},{"key":"D","text":"To eliminate all nervousness immediately"}]'::jsonb,ARRAY['C']::text[] from public.lessons where course_slug='leadership-voice' and slug='masterful-notes-delivered';
