insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,0,'What is the surge of energy many speakers feel just before presenting?',false,'[{"key":"A","text":"Fatigue"},{"key":"B","text":"Adrenaline"},{"key":"C","text":"Distraction"},{"key":"D","text":"Frustration"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='pesky-nerves-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,1,'Which techniques are recommended for calming nerves before speaking?',true,'[{"key":"A","text":"Box Breathing"},{"key":"B","text":"4-7-8 Breathing"},{"key":"C","text":"Power Posing"},{"key":"D","text":"Reading your presentation word for word"}]'::jsonb,ARRAY['A','B','C']::text[] from public.lessons where course_slug='leadership-voice' and slug='pesky-nerves-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,2,'What is the goal when you feel nervous energy before speaking?',false,'[{"key":"A","text":"Eliminate it completely"},{"key":"B","text":"Ignore it"},{"key":"C","text":"Work with it and channel it productively"},{"key":"D","text":"Hide it from the audience"}]'::jsonb,ARRAY['C']::text[] from public.lessons where course_slug='leadership-voice' and slug='pesky-nerves-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,3,'Why can adrenaline begin to work for you rather than against you?',false,'[{"key":"A","text":"You know your message is impactful"},{"key":"B","text":"You know how you are going to deliver it"},{"key":"C","text":"You channel the energy into excitement"},{"key":"D","text":"All of the above"}]'::jsonb,ARRAY['D']::text[] from public.lessons where course_slug='leadership-voice' and slug='pesky-nerves-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,4,'What is the breathing pattern for 4-7-8 Breathing?',false,'[{"key":"A","text":"Inhale for four, hold for four, exhale for four"},{"key":"B","text":"Inhale for four, hold for seven, exhale for eight"},{"key":"C","text":"Inhale for seven, hold for four, exhale for eight"},{"key":"D","text":"Inhale for eight, hold for seven, exhale for four"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='pesky-nerves-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,5,'How does Box Breathing work?',false,'[{"key":"A","text":"Inhale for four, hold for four, exhale for four, hold for four"},{"key":"B","text":"Inhale for four, hold for seven, exhale for eight"},{"key":"C","text":"Take one deep breath, then hold it as long as possible"},{"key":"D","text":"Breathe quickly for thirty seconds"}]'::jsonb,ARRAY['A']::text[] from public.lessons where course_slug='leadership-voice' and slug='pesky-nerves-managed';
