insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,7,'What can a small shift in posture create?',false,'[{"key":"A","text":"A longer presentation"},{"key":"B","text":"A meaningful shift in mindset"},{"key":"C","text":"A need for more slides"},{"key":"D","text":"Less need for preparation"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='pesky-nerves-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,8,'When properly channelled, adrenaline can help you:',false,'[{"key":"A","text":"Perform at a higher level"},{"key":"B","text":"Avoid every possible mistake"},{"key":"C","text":"Speak without preparation"},{"key":"D","text":"Eliminate the need for practice"}]'::jsonb,ARRAY['A']::text[] from public.lessons where course_slug='leadership-voice' and slug='pesky-nerves-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,9,'Over time, regular practice of these techniques can help the surge of energy feel more like:',false,'[{"key":"A","text":"Fear"},{"key":"B","text":"Readiness"},{"key":"C","text":"Confusion"},{"key":"D","text":"Pressure"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='pesky-nerves-managed';
