insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,0,'What can a well-placed question help you do in a key conversation?',true,'[{"key":"A","text":"Lower defensiveness"},{"key":"B","text":"Gather useful information"},{"key":"C","text":"Show that you want to help solve the problem"},{"key":"D","text":"Create a runway to say what you planned regardless of the answer"}]'::jsonb,ARRAY['A','B','C']::text[] from public.lessons where course_slug='leadership-voice' and slug='key-conversations-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,1,'According to the lesson, influence begins:',false,'[{"key":"A","text":"When you present strong evidence"},{"key":"B","text":"When you explain your point of view"},{"key":"C","text":"With how you enter the conversation"},{"key":"D","text":"When the other person agrees with you"}]'::jsonb,ARRAY['C']::text[] from public.lessons where course_slug='leadership-voice' and slug='key-conversations-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,2,'What does CALE stand for?',false,'[{"key":"A","text":"Clarify, Align, Listen, Engage"},{"key":"B","text":"Connect, Ask, Listen, Explain"},{"key":"C","text":"Consider, Ask, Lead, Evaluate"},{"key":"D","text":"Communicate, Act, Lead, Explain"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='key-conversations-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,3,'Which approach is most likely to resonate with an Activator?',false,'[{"key":"A","text":"A direct, concise, action-oriented message"},{"key":"B","text":"A highly detailed explanation with extensive background"},{"key":"C","text":"A message focused mainly on relationships"},{"key":"D","text":"An imaginative message full of possibilities"}]'::jsonb,ARRAY['A']::text[] from public.lessons where course_slug='leadership-voice' and slug='key-conversations-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,4,'Before a key conversation, what should you consider as part of the Connect step?',false,'[{"key":"A","text":"Who is involved, what matters to them, and how they are likely to receive information"},{"key":"B","text":"How many slides you should prepare"},{"key":"C","text":"How long you should speak without pausing"},{"key":"D","text":"Which part of the conversation you can dominate"}]'::jsonb,ARRAY['A']::text[] from public.lessons where course_slug='leadership-voice' and slug='key-conversations-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,5,'Effective listening in a key conversation can help you:',true,'[{"key":"A","text":"Confirm what matters to the other person"},{"key":"B","text":"Understand concerns they may already have"},{"key":"C","text":"Notice where resistance may be coming from"},{"key":"D","text":"Hear the language they are using"},{"key":"E","text":"Prepare an immediate counterargument before they finish speaking"}]'::jsonb,ARRAY['A','B','C','D']::text[] from public.lessons where course_slug='leadership-voice' and slug='key-conversations-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,6,'When you reach the Explain step, what should you generally do?',false,'[{"key":"A","text":"Deliver a long, detailed speech"},{"key":"B","text":"Frame a clear headline, add supporting points, and close with a next step"},{"key":"C","text":"Begin the conversation again from the start"},{"key":"D","text":"Avoid using evidence altogether"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='key-conversations-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,7,'Why does pausing help during a key conversation?',false,'[{"key":"A","text":"It helps you stay composed"},{"key":"B","text":"It prepares people to hear an important idea"},{"key":"C","text":"It gives people time to absorb what you have said"},{"key":"D","text":"All of the above"}]'::jsonb,ARRAY['D']::text[] from public.lessons where course_slug='leadership-voice' and slug='key-conversations-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,8,'What is the purpose of the ACTS Communication Model?',false,'[{"key":"A","text":"To label people permanently by personality type"},{"key":"B","text":"To understand the person, room, and moment so the message is more likely to be heard"},{"key":"C","text":"To determine who should speak first in a meeting"},{"key":"D","text":"To replace the need for preparation"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='key-conversations-managed';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,9,'What is the overall goal of influencing a key conversation?',false,'[{"key":"A","text":"To dominate the discussion"},{"key":"B","text":"To win every disagreement"},{"key":"C","text":"To influence the conversation in a clear, respectful, and useful way"},{"key":"D","text":"To avoid raising concerns altogether"}]'::jsonb,ARRAY['C']::text[] from public.lessons where course_slug='leadership-voice' and slug='key-conversations-managed';
