insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,0,'What is the primary purpose of the ACTS model?',false,'[{"key":"A","text":"To label people by personality type"},{"key":"B","text":"To identify the strongest speaker in a group"},{"key":"C","text":"To understand what others may value and how they may prefer to receive information"},{"key":"D","text":"To replace preparation before a key conversation"}]'::jsonb,ARRAY['C']::text[] from public.lessons where course_slug='leadership-voice' and slug='flexing-your-style-with-acts';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,1,'Which qualities are commonly associated with Activators?',true,'[{"key":"A","text":"Directness"},{"key":"B","text":"Decisiveness"},{"key":"C","text":"Focus on results"},{"key":"D","text":"Preference for lengthy background explanations"}]'::jsonb,ARRAY['A','B','C']::text[] from public.lessons where course_slug='leadership-voice' and slug='flexing-your-style-with-acts';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,2,'When influencing an Activator, what is usually the best approach?',false,'[{"key":"A","text":"Lead with the outcome and make the next step clear"},{"key":"B","text":"Begin with a long history of the issue"},{"key":"C","text":"Focus first on how everyone feels"},{"key":"D","text":"Avoid making a recommendation"}]'::jsonb,ARRAY['A']::text[] from public.lessons where course_slug='leadership-voice' and slug='flexing-your-style-with-acts';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,3,'What do Creators typically value most in a conversation?',false,'[{"key":"A","text":"Possibility, momentum, and energy"},{"key":"B","text":"Detailed process controls"},{"key":"C","text":"Stability and predictability"},{"key":"D","text":"Private reflection before discussion"}]'::jsonb,ARRAY['A']::text[] from public.lessons where course_slug='leadership-voice' and slug='flexing-your-style-with-acts';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,4,'What is one risk of presenting too much detail too early to a Creator?',false,'[{"key":"A","text":"They may feel the opportunity is less engaging"},{"key":"B","text":"They may make a decision too quickly"},{"key":"C","text":"They may become more focused on the facts"},{"key":"D","text":"They may feel more supported"}]'::jsonb,ARRAY['A']::text[] from public.lessons where course_slug='leadership-voice' and slug='flexing-your-style-with-acts';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,5,'When influencing a Team Player, what should you do first?',false,'[{"key":"A","text":"Push quickly for action"},{"key":"B","text":"Build trust and invite their input"},{"key":"C","text":"Focus only on business results"},{"key":"D","text":"Present a detailed risk analysis"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='flexing-your-style-with-acts';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,6,'What do Specialists tend to value most?',false,'[{"key":"A","text":"Accuracy, logic, and quality"},{"key":"B","text":"Speed, visibility, and spontaneity"},{"key":"C","text":"Relationship-building over evidence"},{"key":"D","text":"Creative possibilities without detail"}]'::jsonb,ARRAY['A']::text[] from public.lessons where course_slug='leadership-voice' and slug='flexing-your-style-with-acts';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,7,'Why should you adapt your approach using ACTS?',false,'[{"key":"A","text":"To make the message easier for the other person to receive"},{"key":"B","text":"To better understand what they may value or question"},{"key":"C","text":"To improve the likelihood that your message will be heard"},{"key":"D","text":"All of the above"}]'::jsonb,ARRAY['D']::text[] from public.lessons where course_slug='leadership-voice' and slug='flexing-your-style-with-acts';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,8,'Which statement is most likely to resonate with a Specialist?',false,'[{"key":"A","text":"“I have a good feeling this will work.”"},{"key":"B","text":"“This idea could create real momentum.”"},{"key":"C","text":"“Here is the data, the assumptions, the risks, and how we will manage them.”"},{"key":"D","text":"“Let’s decide quickly and move on.”"}]'::jsonb,ARRAY['C']::text[] from public.lessons where course_slug='leadership-voice' and slug='flexing-your-style-with-acts';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,9,'When ACTS is combined with CALE, it can help you:',true,'[{"key":"A","text":"Connect with greater awareness"},{"key":"B","text":"Ask better questions"},{"key":"C","text":"Listen for what matters"},{"key":"D","text":"Explain in a way that is easier to hear"}]'::jsonb,ARRAY['A','B','C','D']::text[] from public.lessons where course_slug='leadership-voice' and slug='flexing-your-style-with-acts';
