insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,0,'What three conditions commonly make a conversation difficult?',false,'[{"key":"A","text":"Stakes are low, emotions are calm, and opinions agree"},{"key":"B","text":"Stakes are high, emotions are strong, and opinions vary"},{"key":"C","text":"The meeting is long, the room is crowded, and people are tired"},{"key":"D","text":"The speaker lacks slides, notes, and evidence"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='managing-difficult-conversations';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,1,'Under pressure, people commonly respond by:',false,'[{"key":"A","text":"Pausing, reflecting, and agreeing"},{"key":"B","text":"Explaining, persuading, and concluding"},{"key":"C","text":"Fighting, fleeing, or freezing"},{"key":"D","text":"Listening, paraphrasing, and acting"}]'::jsonb,ARRAY['C']::text[] from public.lessons where course_slug='leadership-voice' and slug='managing-difficult-conversations';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,2,'What is the first goal in a difficult conversation?',false,'[{"key":"A","text":"To win the point"},{"key":"B","text":"To regain the ability to think clearly"},{"key":"C","text":"To prove the other person wrong"},{"key":"D","text":"To immediately solve every issue"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='managing-difficult-conversations';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,3,'What can “Look Out” help you notice during a difficult conversation?',true,'[{"key":"A","text":"Changes in tone"},{"key":"B","text":"Body language"},{"key":"C","text":"Withdrawal or tension"},{"key":"D","text":"Defensiveness"}]'::jsonb,ARRAY['A','B','C','D']::text[] from public.lessons where course_slug='leadership-voice' and slug='managing-difficult-conversations';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,4,'What does the “We not Me” skill encourage you to do?',false,'[{"key":"A","text":"Focus on proving that you are right"},{"key":"B","text":"Shift from blame toward a better shared outcome"},{"key":"C","text":"Avoid discussing the issue"},{"key":"D","text":"Let the other person make every decision"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='managing-difficult-conversations';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,5,'Why is it helpful to stick to facts?',false,'[{"key":"A","text":"Facts help cool the conversation down"},{"key":"B","text":"Facts make every conversation shorter"},{"key":"C","text":"Facts eliminate the need for empathy"},{"key":"D","text":"Facts prove that one person is right"}]'::jsonb,ARRAY['A']::text[] from public.lessons where course_slug='leadership-voice' and slug='managing-difficult-conversations';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,6,'Why is mutual purpose and mutual respect important?',false,'[{"key":"A","text":"It makes it safer for both people to speak honestly"},{"key":"B","text":"It helps lower defensiveness"},{"key":"C","text":"It helps people look for a shared goal"},{"key":"D","text":"All of the above"}]'::jsonb,ARRAY['D']::text[] from public.lessons where course_slug='leadership-voice' and slug='managing-difficult-conversations';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,7,'What does it mean to be humbly confident?',false,'[{"key":"A","text":"Avoid taking a position"},{"key":"B","text":"Speak clearly and directly while remaining open to other perspectives"},{"key":"C","text":"Agree with every objection"},{"key":"D","text":"Focus only on the other person’s opinion"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='managing-difficult-conversations';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,8,'What are effective ways to show sincere curiosity?',true,'[{"key":"A","text":"Ask supportive questions"},{"key":"B","text":"Listen to understand rather than simply respond"},{"key":"C","text":"Paraphrase what you are hearing"},{"key":"D","text":"Show empathy"}]'::jsonb,ARRAY['A','B','C','D']::text[] from public.lessons where course_slug='leadership-voice' and slug='managing-difficult-conversations';
insert into public.quiz_questions (lesson_id,position,question,multi,options,answers) select id,9,'What should “Move to Action” include?',false,'[{"key":"A","text":"Leaving the next steps open-ended"},{"key":"B","text":"Agreeing on who does what, and by when"},{"key":"C","text":"Waiting to see what happens"},{"key":"D","text":"Ending the conversation without a decision"}]'::jsonb,ARRAY['B']::text[] from public.lessons where course_slug='leadership-voice' and slug='managing-difficult-conversations';
